def brief(x, name, depth=0):
 ind='  '*depth
 if isinstance(x,dict):
  print(f'{ind}{name}: dict keys={list(x.keys())}')
  if depth<2:
   for k,v in x.items(): brief(v,str(k),depth+1)
 elif isinstance(x,np.ndarray):
  finite=np.isfinite(x) if np.issubdtype(x.dtype,np.number) else None
  desc=f'array shape={x.shape} dtype={x.dtype}'
  if finite is not None: desc+=f' finite={finite.sum()}/{x.size}'
  if x.dtype==object and x.size<=40: desc+=f' values={x.tolist()}'
  print(ind+name+': '+desc)
 elif isinstance(x,(list,tuple)):
  print(f'{ind}{name}: {type(x).__name__} len={len(x)}')
  for i,v in enumerate(x[:3]): brief(v,f'[{i}]',depth+1)
